package org.sleepwell.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import androidx.activity.*;import java.util.*;import org.json.*;
/** Private visible real upper-body pose detector, shared by quiet preview and one current challenge unit. */
public final class PoseActivity extends ComponentActivity {
 static final int CHALLENGE=794,FALLBACK=RESULT_FIRST_USER;private String request,run,mode,status="Camera stays off until you start.",error="";private int unit;private boolean resumed,pending,done,math,details;private long generation,started;private PoseCamera.Port camera;private final PoseHold hold=new PoseHold();private CameraTaskOwner cameraOwner;private TextView live;private final Handler handler=new Handler(Looper.getMainLooper());
 static Intent preview(Activity a){return RecordUi.intent(a,PoseActivity.class).putExtra("mode","preview").putExtra("request",UUID.randomUUID().toString());}
 static Intent challenge(Activity a,String run,int unit,String nonce){return RecordUi.intent(a,PoseActivity.class).putExtra("mode","challenge").putExtra("run",run).putExtra("unit",unit).putExtra("request",nonce);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();mode=getIntent().getStringExtra("mode");if(!Set.of("preview","challenge").contains(mode))throw new IllegalArgumentException();run=mode.equals("preview")?request:getIntent().getStringExtra("run");unit=mode.equals("preview")?0:getIntent().getIntExtra("unit",-1);if(run==null||run.isBlank()||run.length()>128||unit<0)throw new IllegalArgumentException();if(saved!=null){done=saved.getBoolean("done");math=saved.getBoolean("math");details=saved.getBoolean("details");error=saved.getString("error","");status="Camera paused. Start again when ready.";}}catch(Exception invalid){finish();return;}cameraOwner=CameraTaskOwner.attach(this,new JSONArray(java.util.Arrays.asList(getClass().getName(),mode,run,unit,request)).toString(),saved);if(mode.equals("challenge")){setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});render();}
 private boolean current(){if(!resumed||isDestroyed()||isFinishing())return false;if(mode.equals("preview"))return true;try{if(!AlarmService.current(this,run)||Prefs.number(this,"challengeCompleted",-1)!=unit)return false;Alarm active=Alarm.read(new JSONObject(Prefs.text(this,"active_alarm","{}")));ChallengeRoutine.Position position=active.challenges().at(unit);return position!=null&&position.task.type.equals("Pose");}catch(Exception invalid){return false;}}
 private final Runnable verify=new Runnable(){public void run(){if(!resumed)return;if(!current()){stop();setResult(RESULT_CANCELED);finish();return;}if(cameraOwner.pending(PoseActivity.this)){completePending();handler.postDelayed(this,250);return;}if(cameraOwner.closing(PoseActivity.this)){if(cameraOwner.clean()){camera=null;render();}handler.postDelayed(this,250);return;}if(camera!=null&&SystemClock.elapsedRealtime()-started>=60000){stop();error="The one-minute attempt ended. Retry or use Math.";render();}handler.postDelayed(this,250);}};
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,mode.equals("preview")?"Pose preview":"Raise both hands",this::back);Design.space(body,12);if(cameraOwner!=null&&(cameraOwner.pending(this)||cameraOwner.closing(this))){cleanupView(body);return;}if(details){Design.text(body,"Bundled Google ML Kit",22,600,Design.INK);Design.space(body,12);Design.text(body,"The bundled beta model runs on this device without a model download. The detector/model is a proprietary Google dependency, not an open model. Google may receive SDK usage and performance metrics. SleepWell saves no camera images or body templates.",15,400,Design.MUTED);Design.space(body,12);Design.text(body,"The detector follows the most prominent person; it cannot verify that nobody else is present. Photos or screens may pass. Lighting, clothing, occlusion and camera angle can affect results. This is not identity, liveness or medical assessment.",14,400,Design.MUTED);Design.space(body,12);Design.text(body,"Terms: https://developers.google.com/ml-kit/terms",13,400,Design.MUTED);Design.fixedAction(body,"Back to pose",()->{details=false;render();});return;}if(done){Design.text(body,math?"Math alternative completed":"Hands-raised pose detected",25,600,Design.INK);Design.text(body,"This checks a visible pose, not identity, liveness or health.",13,400,Design.MUTED);Design.button(body,"Try again",false,()->{done=math=false;status="Camera stays off until you start.";render();});Design.fixedAction(body,"Return",this::back);return;}if(math){WakePuzzleView.math(body,run,unit,0,()->current()&&hasWindowFocus(),()->{done=true;render();});return;}Design.text(body,"Place your phone on a stable surface. Step back so your head, hands and hips are visible, then raise both hands above your head.",15,400,Design.MUTED);Design.space(body,10);Design.text(body,"Uses Google’s bundled ML Kit detector. Camera images are processed on this device; the SDK may send usage and performance metrics to Google.",12,400,Design.MUTED);Design.space(body,12);FrameLayout frame=new FrameLayout(this);frame.setBackground(Design.shape(this,Design.SOFT,18));frame.setClipToOutline(true);frame.setContentDescription("Pose front camera preview");if(camera!=null){View preview=camera.preview();if(preview.getParent() instanceof ViewGroup parent)parent.removeView(preview);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));}else{TextView empty=Design.text(this,"Front camera is paused",15,500,Design.MUTED);empty.setGravity(Gravity.CENTER);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));}body.addView(frame,new LinearLayout.LayoutParams(-1,Design.dp(this,300)));Design.space(body,12);live=Design.text(body,status,14,500,Design.BROWN);live.setContentDescription("Pose detection status");live.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);if(camera==null){PoseCameraAccess.Status permission=PoseCameraAccess.status(this);String label=permission==PoseCameraAccess.Status.NEEDED?"Allow pose camera":permission==PoseCameraAccess.Status.SETTINGS?"Open pose camera settings":"Start pose camera";Button start=Design.button(body,label,true,this::startPressed);if(permission==PoseCameraAccess.Status.UNSUPPORTED){start.setEnabled(false);Design.text(body,"A front camera is unavailable. Use Math instead.",13,400,Design.MUTED);}}else Design.button(body,"Pause pose camera",false,()->{stop();status="Camera paused. Start again when ready.";render();});Design.space(body,10);Design.item(body,"info","Detector and privacy details",null,()->{stop();details=true;render();});LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,0xffa93919);issue.setContentDescription("Pose camera error");}Design.button(footer,"Use Math instead",false,this::chooseMath);}
 private void startPressed(){if(!current()||done||math)return;error="";PoseCameraAccess.Status permission=PoseCameraAccess.status(this);if(permission==PoseCameraAccess.Status.READY){pending=false;begin();return;}if(permission==PoseCameraAccess.Status.UNSUPPORTED){error="A front camera is required. Use Math instead.";render();return;}pending=true;try{PoseCameraAccess.request(this);}catch(RuntimeException failure){pending=false;error="Camera permission settings could not open. Use Math or retry.";render();}}
 private void begin(){if(!current()||done||math||PoseCameraAccess.status(this)!=PoseCameraAccess.Status.READY)return;if(!stop()){error="Camera cleanup failed. Return and choose Math.";render();return;}long ticket=++generation;hold.reset();try{camera=PoseCamera.factory.create(this);cameraOwner.bind(this,camera::close,camera::released);started=SystemClock.elapsedRealtime();status="Keep your head, hands and hips in frame. Raise both hands above your head.";camera.start(new PoseCamera.Listener(){public void frame(PoseHold.Sample sample,String issue){if(ticket!=generation||camera==null||!current()||!hasWindowFocus())return;if(PoseCameraAccess.status(PoseActivity.this)!=PoseCameraAccess.Status.READY){stop();error="Camera permission changed. Allow it again or use Math.";render();return;}long now=SystemClock.elapsedRealtime();if(hold.frame(sample,now)){respond(RESULT_OK,sample.at);return;}status=sample!=null&&sample.raised()?"Hold your raised hands steady · "+hold.progress()+"%":issue==null||issue.isBlank()?"Keep your upper body in view and raise both hands above your head.":issue;if(live!=null)live.setText(status);}public void error(String message){if(ticket!=generation||!current())return;stop();error=message;render();}});render();}catch(RuntimeException failure){stop();error="The pose detector could not start. Retry or use Math.";render();}}
 private boolean stop(){generation++;hold.reset();if(cameraOwner==null)return camera==null;boolean clean=cameraOwner.stop(this);if(clean)camera=null;return clean;}
 private void chooseMath(){if(!current())return;pending=false;respond(FALLBACK,0);}
 private void respond(int result,long captured){if(!current())return;cameraOwner.earn(this,result,captured,new Intent().putExtra("run",run).putExtra("unit",unit).putExtra("request",request).putExtra("captured",captured));stop();if(!completePending())render();}
 private boolean completePending(){
  if(!current()||!hasWindowFocus()||!getWindow().getDecorView().isAttachedToWindow()||!cameraOwner.pending(this)||!cameraOwner.clean())return false;
  CameraTaskOwner.Pending earned=cameraOwner.take(this);if(earned==null)return false;camera=null;
  if(mode.equals("preview")){if(earned.result==FALLBACK)math=true;else done=true;render();return true;}
  setResult(earned.result,earned.data);finish();return true;
 }
 private void cleanupView(LinearLayout body){
  Design.text(body,"Release camera",25,600,Design.INK);Design.space(body,12);
  Design.text(body,"Camera callbacks are stopped. Continue after this attempt’s camera and analysis have fully closed. Any earned result is retained.",14,400,Design.MUTED);
  Design.button(body,"Retry camera cleanup",true,()->{if(!current()||!hasWindowFocus())return;stop();if(!completePending())render();});
  Design.fixedAction(body,"Cancel",()->{details=false;back();});
 }
 private void back(){if(details){details=false;render();return;}pending=false;if(cameraOwner!=null)cameraOwner.cancel(this);stop();setResult(RESULT_CANCELED);finish();}
 @Override protected void onResume(){super.onResume();resumed=true;if(!current()){finish();return;}verify.run();if(pending&&PoseCameraAccess.status(this)==PoseCameraAccess.Status.READY){pending=false;begin();}else if(camera==null)render();}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(verify);stop();super.onPause();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code!=PoseCameraAccess.REQUEST)return;if(PoseCameraAccess.status(this)==PoseCameraAccess.Status.READY){pending=true;if(resumed){pending=false;begin();}}else{pending=false;error="Camera access was not allowed. Use Math or allow it in settings.";render();}}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);else if(camera!=null){stop();status="Camera paused. Start again when ready.";if(resumed)render();}}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);if(cameraOwner!=null)cameraOwner.save(this,saved);saved.putBoolean("done",done);saved.putBoolean("math",math);saved.putBoolean("details",details);saved.putString("error",error);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);stop();if(cameraOwner!=null)cameraOwner.detach(this,isChangingConfigurations());super.onDestroy();}
}
